import { HttpErrorResponse, HttpResponse } from '@angular/common/http';
import { Component, OnInit } from '@angular/core';
import { medical_checkup } from '../../model/medical_checkup';
import { DossierService } from '../../services/dossier.service';
import { treatmenthistory } from '../../model/treatmenthistory'
import { travel_residency } from '../../model/travel_residency';
import { discrepancy } from '../../model/discrepancy';
import { sample } from '../../model/sample';
import { diognosis } from '../../model/diognosis';
import { Router } from '@angular/router';


@Component({
  selector: 'app-dossier',
  templateUrl: './dossier.component.html',
  styleUrls: ['./dossier.component.css']
})
export class DossierComponent implements OnInit {

  constructor(private dossierservice: DossierService , private router : Router) { }

  ngOnInit(): void {
    const id = localStorage.getItem('patientidentifier');
    this.get_all_medical_checkup(id);
    this.get_all_treatmenthistory(id);
    this.get_all_travel_residency(id);
    this.get_all_discrepancy(id);
    this.get_all_sample(id);
  }

  /* mediacl checkup */
  medical_checkups: medical_checkup[];
  content_medical_checkup: boolean;
  public get_all_medical_checkup(patient_identifier: string) {
    this.dossierservice.get_medical_checkup(patient_identifier).subscribe(
      data => {
        if (data.status == 200) {
          this.medical_checkups = data.body;
          this.content_medical_checkup = true;
        }
        else if (data.status == 204) {
          this.content_medical_checkup = false;
        }
      },
      (error: HttpErrorResponse) => {
        if (error) { console.log(error.message); }
      }
    )
  }

  /* treatemant history */
  treatmenthistorys: treatmenthistory[];
  content_treatmenthistorys: boolean;
  public get_all_treatmenthistory(patient_identifier: string) {
    this.dossierservice.get_treatmenthistory(patient_identifier).subscribe(
      data => {
        if (data.status == 200) {
          this.treatmenthistorys = data.body;
          this.content_treatmenthistorys = true;
        }
        else if (data.status == 204) { this.content_treatmenthistorys = false; }
      },
      (error: HttpErrorResponse) => {
        if (error) { console.log(error.message); }
      }
    )
  }

  /*travel_residency*/
  travel_residencys: travel_residency[];
  content_travel_residencys: boolean;
  public get_all_travel_residency(patient_identifier: string) {
    this.dossierservice.get_travel_residency(patient_identifier).subscribe(
      data => {
        if (data.status == 200) {
          this.travel_residencys = data.body;
          this.content_travel_residencys = true;
        }
        else if (data.status == 204) {
          this.content_travel_residencys = false;
        }
      },
      (error: HttpErrorResponse) => {
        if (error) { console.log(error.message); }
      }
    )
  }
  /*discrepancy*/
  discrepancys: discrepancy[];
  content_discrepancy: boolean;
  public get_all_discrepancy(patient_identifier: string) {
    this.dossierservice.get_discrepancy(patient_identifier).subscribe(
      data => {
        if (data.status == 200) {
          this.content_discrepancy = true;
          this.discrepancys = data.body;
        }
        else if (data.status == 204) {
          this.content_discrepancy = false;
        }
      },
      (error: HttpErrorResponse) => {
        if (error) { console.log(error.message); }
      }
    )

  }

  /* sample */
  samples: sample[]
  content_sample: boolean;
  public get_all_sample(patient_identifier: string) {
    this.dossierservice.get_sample(patient_identifier).subscribe(
      data => {
        if (data.status == 200) {
          this.content_sample = true;
          this.samples = data.body;
        }
        else if (data.status == 204) {
          this.content_sample = false;
        }
      },
      (error: HttpErrorResponse) => {
        if (error) { console.log(error.message); }
      }
    )
  }

  /* diognosis*/
  condition = false;
  text = "";
  diognosis: diognosis[]
  pass(idsample: string) {
    this.dossierservice.get_diognosis(idsample).subscribe(
      data => {
        if (data.status == 200) {
          this.diognosis = data.body
          this.condition = true
        }
        else if (data.status)
         {
          this.condition = false;
          this.text = "This sample hasent any diognosis";
        }
      },
      (error: HttpErrorResponse) => {
        if (error) { console.log(error.message); console.log(error.status) }
      }
    )
  }
}


